    frames = []

    for color in {v for row in grid for v in row if v != 0}:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        if r0 == r1 or c0 == c1:
            continue
        border = [(r, c) for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)
                  if r in (r0, r1) or c in (c0, c1)]
        if all(grid[r][c] == color for r, c in border):
            frames.append((r0, r1, c0, c1, color))

    frame_colors = {f[4] for f in frames}
    counts = {}
    for row in grid:
        for v in row:
            if v != 0 and v not in frame_colors:
                counts[v] = counts.get(v, 0) + 1

    markers = sorted(counts, key=lambda v: counts[v])
    frames.sort(key=lambda f: sum(
        1 for r in range(f[0] + 1, f[1]) for c in range(f[2] + 1, f[3])
        if (r + c) % 2 == 0
    ))

    out = [[0] * w for _ in range(h)]
    for i, (r0, r1, c0, c1, color) in enumerate(frames):
        for c in range(c0, c1 + 1):
            out[r0][c] = out[r1][c] = color
        for r in range(r0, r1 + 1):
            out[r][c0] = out[r][c1] = color
        if i < len(markers):
            marker = markers[i]
            for r in range(r0 + 1, r1):
                for c in range(c0 + 1, c1):
                    if (r + c) % 2 == 0:
